```java
// PRIMITIVES — == compares values
int a = 5, b = 5;
System.out.println(a == b);  // true — same value

// OBJECTS — == compares references
String s1 = new String("hello");
String s2 = new String("hello");
System.out.println(s1 == s2);       // false — different objects
System.out.println(s1.equals(s2));  // true — same content

// GOTCHA: Integer cache
Integer i1 = 100, i2 = 100;
System.out.println(i1 == i2);   // true (-128 to 127 are cached)
Integer i3 = 200, i4 = 200;
System.out.println(i3 == i4);   // false! (200 is outside cache range)
System.out.println(i3.equals(i4)); // true — always correct
```

```java
// Comparable — inside the class (natural ordering)
class Employee implements Comparable<Employee> {
    String name; int salary;
    @Override
    public int compareTo(Employee other) {
        return Integer.compare(this.salary, other.salary); // sort by salary
    }
}

// Comparator — external, custom ordering
Comparator<Employee> byName = (e1, e2) -> e1.name.compareTo(e2.name);

List<Employee> list = new ArrayList<>();
Collections.sort(list);              // uses Comparable (natural order)
list.sort(byName);                   // uses Comparator (name order)
list.sort(Comparator.comparing(e -> e.salary)); // inline comparator
```

```java
// Within cache range (-128 to 127) — same cached object
Integer a = 100;
Integer b = 100;
System.out.println(a == b);      // true (same cached object)
System.out.println(a.equals(b)); // true

// Outside cache range — different objects each time
Integer x = 200;
Integer y = 200;
System.out.println(x == y);      // false (different objects!)
System.out.println(x.equals(y)); // true — always use equals()

// Why it exists:
// Java pre-creates Integer objects for common values
// so Integer.valueOf(100) always returns the same object
```

**The safe rule**: Always use `.equals()` for Integer comparison. Never rely on `==` for Integer objects.

```java
// if-else — flexible, handles ranges
if (score >= 90) grade = "A";
else if (score >= 80) grade = "B";
else if (score >= 70) grade = "C";
else grade = "F";

// switch — discrete values, more readable for many cases
// Java 14+ switch expression
String dayType = switch (dayOfWeek) {
    case 1, 7 -> "Weekend";
    case 2, 3, 4, 5, 6 -> "Weekday";
    default -> "Invalid";
};

// Traditional switch — for older Java
switch (status) {
    case "ACTIVE": ...; break;
    case "INACTIVE": ...; break;
    case "PENDING": ...; break;
    default: ...;
}
```

```java
// while — condition checked BEFORE body
// Might never execute if condition starts false
int x = 10;
while (x < 5) {  // never runs — x is already >= 5
    System.out.println(x);
}

// do-while — body runs FIRST, condition checked AFTER
// Menu example — always show menu at least once
int choice;
do {
    System.out.println("1. View  2. Add  3. Exit");
    choice = scanner.nextInt();
    processChoice(choice);
} while (choice != 3);  // note the semicolon!

// Input validation — read until valid
int age;
do {
    System.out.println("Enter age (1-120):");
    age = scanner.nextInt();
} while (age < 1 || age > 120);
```

```java
String a = "Apple";
String b = "apple";
String c = "Banana";

// == compares references — WRONG for content
System.out.println(a == b);               // false (different objects usually)

// equals() — case-sensitive content comparison
System.out.println(a.equals(b));          // false ('A' != 'a')
System.out.println(a.equalsIgnoreCase(b));// true (ignores case)

// compareTo() — lexicographic (for sorting)
System.out.println(a.compareTo(c));  // negative — "Apple" comes before "Banana"
System.out.println(c.compareTo(a));  // positive — "Banana" comes after "Apple"
System.out.println(a.compareTo("Apple")); // 0 — equal

// Null-safe comparison
System.out.println(Objects.equals(a, null));  // false — no NPE
```
